class Solution:
    def partition(self, s: str) -> List[List[str]]:
        n = len(s)
        ok = [[False] * n for _ in range(n)]
        for i in range(n - 1, -1, -1):
            for j in range(i, n):
                ok[i][j] = s[i] == s[j] and (j - i < 2 or ok[i + 1][j - 1])
        res, path = [], []

        def dfs(start: int) -> None:
            if start == n:
                res.append(path[:])
                return
            for end in range(start, n):
                if ok[start][end]:
                    path.append(s[start:end + 1])
                    dfs(end + 1)
                    path.pop()

        dfs(0)
        return res

