        return False

class Solution:
    def searchRange(self, nums: List[int], target: int) -> List[int]:
        def lower(v: int) -> int:
            l, r = 0, len(nums)
            while l < r:
                mid = (l + r) // 2
                if nums[mid] < v:
                    l = mid + 1
                else:
                    r = mid
            return l

        left = lower(target)
        if left == len(nums) or nums[left] != target:
            return [-1, -1]
        return [left, lower(target + 1) - 1]

class Solution:
    def search(self, nums: List[int], target: int) -> int:
        l, r = 0, len(nums) - 1
        while l <= r:
            mid = (l + r) // 2
            if nums[mid] == target:
                return mid
            if nums[l] <= nums[mid]:
                if nums[l] <= target < nums[mid]:
                    r = mid - 1
                else:
                    l = mid + 1
            else:
                if nums[mid] < target <= nums[r]:
                    l = mid + 1
                else:
                    r = mid - 1
        return -1

