        a, b = nums1, nums2
        if len(a) > len(b):
            a, b = b, a
        m, n = len(a), len(b)
        half = (m + n + 1) // 2
        l, r = 0, m
        while l <= r:
            i = (l + r) // 2
            j = half - i
            la = a[i - 1] if i > 0 else float("-inf")
            ra = a[i] if i < m else float("inf")
            lb = b[j - 1] if j > 0 else float("-inf")
            rb = b[j] if j < n else float("inf")
            if la <= rb and lb <= ra:
                if (m + n) % 2:
                    return float(max(la, lb))
                return (max(la, lb) + min(ra, rb)) / 2
            if la > rb:
                r = i - 1
            else:
                l = i + 1
        return 0.0

