class MedianFinder:

    def __init__(self):
        self.lo = []
        self.hi = []

    def _push(self, h: List[int], v: int) -> None:
        h.append(v)
        i = len(h) - 1
        while i > 0:
            p = (i - 1) // 2
            if h[i] >= h[p]:
                break
            h[i], h[p] = h[p], h[i]
            i = p

    def _pop(self, h: List[int]) -> int:
        top = h[0]
        last = h.pop()
        if h:
            h[0] = last
            i, n = 0, len(h)
            while True:
                m = i
                l, r = 2 * i + 1, 2 * i + 2
                if l < n and h[l] < h[m]:
                    m = l
                if r < n and h[r] < h[m]:
                    m = r
                if m == i:
                    break
                h[i], h[m] = h[m], h[i]
                i = m
        return top

    def addNum(self, num: int) -> None:
        self._push(self.lo, -num)
        self._push(self.hi, -self._pop(self.lo))
        if len(self.hi) > len(self.lo):
            self._push(self.lo, -self._pop(self.hi))

    def findMedian(self) -> float:
        if len(self.lo) > len(self.hi):
            return float(-self.lo[0])
        return (-self.lo[0] + self.hi[0]) / 2

